            w[s] = rec[s]

    if 'authors' in edition:
        edition_authors = edition['authors']
        record_authors = rec.get('authors', [])
        if len(edition_authors) != len(record_authors):
            raise Exception('Edition and record author counts do not match')
        w['authors'] = []
        for akey, author in zip(edition_authors, record_authors):
            work_author = {'type': {'key': '/type/author_role'}, 'author': akey}
            if author.get('role'):
